<template><div class="content-images"><div v-for="(image,i) in modelValue" :key="image" class="image-item"><el-image :src="url(image)" fit="cover" style="width:130px;height:80px" /><div><el-button link :disabled="disabled||busy||i===0" @click="move(i,-1)">前移</el-button><el-button link :disabled="disabled||busy||i===modelValue.length-1" @click="move(i,1)">后移</el-button><el-button link type="danger" :disabled="disabled||busy" @click="emit('update:modelValue',modelValue.filter((_,n)=>n!==i))">移除</el-button></div></div><el-upload v-if="modelValue.length<limit" accept="image/png,image/jpeg" :show-file-list="false" :disabled="disabled||busy" :http-request="upload"><el-button :disabled="disabled" :loading="busy">上传图片</el-button></el-upload></div></template>
<script setup>
import {ref,onBeforeUnmount} from 'vue';import {ElMessage} from 'element-plus';import {uploadContent} from '@/api/content';import {rewardImage} from '@/api/rewards';import {getToken} from '@/utils/auth'
const props=defineProps({modelValue:{type:Array,default:()=>[]},limit:{type:Number,default:9},disabled:Boolean}),emit=defineEmits(['update:modelValue','busy']),busy=ref(false);let generation=0
const url=p=>p==='/static/player-equipment-banner.jpg'?'https://ceshisss.oksja.cn'+p:rewardImage(p)
onBeforeUnmount(()=>{generation++;emit('busy',false)})
function move(i,delta){const next=[...props.modelValue];[next[i],next[i+delta]]=[next[i+delta],next[i]];emit('update:modelValue',next)}
async function upload(options){if(busy.value||props.disabled)return;busy.value=true;emit('busy',true);const v=++generation,token=getToken();try{if(options.file.size>5*1024*1024)throw Error('图片需在 5MB 内');const r=await uploadContent(options.file);if(v===generation&&token===getToken()&&props.modelValue.length<props.limit)emit('update:modelValue',[...props.modelValue,r.data.url]);options.onSuccess(r)}catch(e){if(v===generation)ElMessage.error(e.message||'上传失败');options.onError(e)}finally{if(v===generation){busy.value=false;emit('busy',false)}}}
</script>
<style scoped>.content-images{display:flex;gap:12px;flex-wrap:wrap;align-items:center}.image-item{border:1px solid #e8e8e8;padding:8px;border-radius:8px}</style>
